const parse = (value) => {
  if (typeof value !== 'string') return value ?? {};
  try { return JSON.parse(value); } catch { return {}; }
};
const clean = (value, limit) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, limit);
const input = items[0]?.json ?? {};
const body = parse(input.body ?? input);
const text = clean(body.text ?? body.thought, 600);
if (!text) throw new Error('night-dump text is required');
const lower = text.toLowerCase();
const tests = [
  ['action', /\b(todo|need to|must|should|fix|email|call|book|schedule|finish)\b/],
  ['research', /\b(research|learn|read|look up|compare|investigate|why|how does)\b/],
  ['remember', /\b(remember|don't forget|birthday|appointment|bring|take)\b/],
  ['worry', /\b(worried|anxious|afraid|concern|stress|what if)\b/],
  ['idea', /\b(idea|could|maybe|build|create|try|what about)\b/],
];
const category = tests.find(([, pattern]) => pattern.test(lower))?.[0] ?? 'other';
const now = new Date().toISOString();
const state = $getWorkflowStaticData('global');
const queue = Array.isArray(state.nightDump) ? state.nightDump : [];
queue.push({
  id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
  text,
  category,
  capturedAt: now,
});
state.nightDump = queue.slice(-100);
return [];

const state = $getWorkflowStaticData('global');
const queue = Array.isArray(state.nightDump) ? state.nightDump : [];
if (!queue.length) return [];
const order = ['action', 'idea', 'research', 'remember', 'worry', 'other'];
const labels = { action: 'Actions', idea: 'Ideas', research: 'Research', remember: 'Remember', worry: 'Set down overnight', other: 'Other' };
const fit = (value, limit = 850) => {
  const safe = String(value ?? '').replaceAll('@', '@\u200b').trim();
  return safe.length <= limit ? safe : safe.slice(0, limit - 3).trimEnd() + '...';
};
const fields = order.flatMap((category) => {
  const entries = queue.filter((entry) => entry.category === category);
  if (!entries.length) return [];
  const shown = entries.slice(0, 8).map((entry) => `- ${entry.text}`).join('\n');
  const overflow = entries.length > 8 ? `\n- ...and ${entries.length - 8} more` : '';
  return [{ name: labels[category], value: fit(shown + overflow) }];
});
const now = new Date().toISOString();
return [{ json: {
  deliveredIds: queue.map((entry) => entry.id),
  discordEmbed: {
    title: `Morning mind sort | ${queue.length} thought${queue.length === 1 ? '' : 's'}`,
    description: 'Captured without waking tomorrow-you. Choose what deserves action; the rest can remain ideas.',
    color: 0x89b4fa,
    fields,
    footer: { text: 'Loom night brain dump' },
    timestamp: now,
  },
} }];

const delivered = new Set($('Prepare morning sort').first().json.deliveredIds ?? []);
const state = $getWorkflowStaticData('global');
const queue = Array.isArray(state.nightDump) ? state.nightDump : [];
state.nightDump = queue.filter((entry) => !delivered.has(entry.id));
state.lastNightDumpDelivery = new Date().toISOString();
return [];
